//! 🎟️ Original Unicode authority reaches retained rows and physical source-owner backing.
use super::*;
use semio_framework_2d_text_font::work::FontWorkLedger;
use semio_framework_value::{RetainedCloneGrant,RetirementDemand};
fn run(mut advance:impl FnMut(&mut FontWorkLedger)->Result<FontProgress,&'static str>){let mut demand=RetirementDemand::default();for _ in 0..100000{let mut denied=FontWorkLedger::new(RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:128});let before=advance(&mut denied).unwrap();assert!(!before.done);assert_eq!((denied.receipt().copied_bytes,denied.receipt().retained_capacity_bytes),(0,0));let mut ledger=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth});let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||advance(&mut ledger).unwrap());let receipt=ledger.receipt();assert!(!physical.overflowed);assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,receipt.released_bytes);demand=if ledger.blocked(){ledger.next_demand()}else{RetirementDemand::default()};if result.done{return;}}panic!("Unicode original fixture stalled")}
#[test]
fn original_unicode_normalization_and_clusters_share_neutral_authority_cases(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut source=UnicodeDataAdmissionJob::new(StaticFontBytes(UNICODE_BYTES),1000000);run(|work|source.advance(1,work));let data=source.take_result().unwrap();for row in fixture["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();let mut normalization=normalize::UnicodeNormalizationCursor::new(data.layout,UNICODE_BYTES,text,1048576,1000000000);run(|work|normalization.advance(UNICODE_BYTES,text,1,work));let output=normalization.take_result().unwrap();let actual=output.iter().map(|row|char::from_u32(row.scalar).unwrap()).collect::<String>();assert_eq!(actual,row["nfc"].as_str().unwrap());let mut cluster=cluster::UnicodeGraphemeCursor::new(data.layout,UNICODE_BYTES,&output,1000000000);run(|work|cluster.advance(UNICODE_BYTES,&output,1,work));close(cluster);close(output);close(normalization);}close(data);close(source);}
